class Graph {
    private static final long INF=1L<<50;
    private final long[][] distance;
    public Graph(int n,int[][] edges){
        distance=new long[n][n];
        for(int i=0;i<n;i++){
            Arrays.fill(distance[i],INF);
            distance[i][i]=0;
        }
        for(int[] edge:edges)distance[edge[0]][edge[1]]=Math.min(distance[edge[0]][edge[1]],edge[2]);
        for(int middle=0;middle<n;middle++)for(int from=0;from<n;from++)for(int to=0;to<n;to++)distance[from][to]=Math.min(distance[from][to],distance[from][middle]+distance[middle][to]);
    }
    public void addEdge(int[] edge){
        int from=edge[0],to=edge[1],weight=edge[2];
        if(weight>=distance[from][to])return;
        for(int start=0;start<distance.length;start++)if(distance[start][from]<INF)for(int end=0;end<distance.length;end++)if(distance[to][end]<INF)distance[start][end]=Math.min(distance[start][end],distance[start][from]+weight+distance[to][end]);
    }
    public int shortestPath(int node1,int node2){
        return distance[node1][node2]>=INF?-1:(int)distance[node1][node2];
    }
}

